// The skin tables: every colour token of every skin, and what an accent other
// than the skin's own changes.
//
// Until P4.5 this file was generated by `scripts/export_nsh_theme.py` from the
// GPUI palette tables; that one-off tool left the tree with the old client, so
// the tables are maintained by hand now. `nsh` was added the same way: a
// neutral surface set from the design guide, not a copy of a GPUI skin.
//
// `SKIN_TOKENS` holds every colour token of each skin and appearance for
// the accent that skin ships with; `ACCENT_OVERRIDES` holds only what
// another accent changes, so `theme/index.ts` can compose skin x accent
// at run time instead of carrying 6 x 6 copies of the same table.

export type SkinName = "default" | "glass" | "archive" | "mist" | "limbus" | "nsh" | "bettbox";
export type AccentName =
  | "crimson"
  | "rose"
  | "blue"
  | "amber"
  | "emerald"
  | "violet"
  | "limbus-brass";

/** Colour tokens by the theme's CSS variable name, without the `--`. */
export type SchemeTokens = Record<string, string>;

/** Radius scale per skin, in points. */
export const SKIN_RADII: Record<SkinName, Record<string, string>> = {
  "default": { "radius-sm": "4px", "radius": "6px", "radius-lg": "8px", "radius-xl": "12px" },
  "glass": { "radius-sm": "6px", "radius": "10px", "radius-lg": "14px", "radius-xl": "18px" },
  "archive": { "radius-sm": "2px", "radius": "4px", "radius-lg": "6px", "radius-xl": "8px" },
  "mist": { "radius-sm": "0px", "radius": "2px", "radius-lg": "4px", "radius-xl": "6px" },
  "limbus": { "radius-sm": "0px", "radius": "0px", "radius-lg": "0px", "radius-xl": "0px" },
  // The design guide's starting point (6pt controls) with containers one and
  // two steps softer, so the containment hierarchy stays visible.
  "nsh": { "radius-sm": "4px", "radius": "6px", "radius-lg": "10px", "radius-xl": "14px" },
  // A phone app's cards: 16pt surfaces over a tinted page, controls just inside.
  "bettbox": { "radius-sm": "8px", "radius": "10px", "radius-lg": "16px", "radius-xl": "20px" },
};

/** The accent a skin is designed around (Limbus is brass, the rest crimson). */
export const SKIN_DEFAULT_ACCENT: Record<SkinName, AccentName> = {
  "default": "crimson",
  "glass": "crimson",
  "archive": "crimson",
  "mist": "crimson",
  "limbus": "limbus-brass",
  "nsh": "crimson",
  "bettbox": "rose",
};

